        h24=torch.tensor(H3[ti_,24,q].astype(np.float32)); a_,b_,c_=[int(x) for x in tk3[ti_,q,:3]]
        obs = float(tl3[ti_,q,0]-tl3[ti_,q,2])
        errs['w'].append(readout_gap(h24,a_,c_,gfin)-obs); errs['1+w'].append(readout_gap(h24,a_,c_,1+gfin)-obs)
print({k_: (round(np.mean(np.abs(v_)),3), round(np.median(v_),3)) for k_,v_ in errs.items()}, 'n=',len(errs['w']))
